set-variable.value:
@{
                string tenant = "{{claude-target-tenant}}";
                string client = "{{claude-app-client}}";
                string identity = "{{claude-uami-client}}";
                string endpoint = "{{claude-target-endpoint}}";
                string guid = @"\A[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\z";
                if (new[] { tenant, client, identity }.Any(v => !System.Text.RegularExpressions.Regex.IsMatch(v, guid) || v == Guid.Empty.ToString())) { return false; }
                if (!System.Text.RegularExpressions.Regex.IsMatch(endpoint, @"\Ahttps:" + "/" + @"/mf-claude-[a-z0-9-]{3,48}\.services\.ai\.azure\.com\z")) { return false; }
                if (context.Subscription == null || context.Subscription.Id != "{{claude-proxy-subscription}}") { return false; }
                if (context.Variables.GetValueOrDefault<bool>("noReplay", false) || context.Request.Method != "POST") { return false; }
                string model = context.Variables.GetValueOrDefault<string>("model", "");
                string path = context.Request.MatchedParameters.GetValueOrDefault("path", "");
                if (path != "deployments/" + model + "/chat/completions") { return false; }
                JArray backends = (JArray)context.Variables["listBackends"];
                if (backends.Count != 1) { return false; }
                JObject backend = (JObject)backends[0];
                return backend.Value<string>("auth") == "CLAUDE_FEDERATED"
                    && backend.Value<string>("url") == endpoint + "/anthropic"
                    && backend.Value<string>("path") == "anthropic"
                    && backend.Value<string>("deployment") == model;
            }

@{
                IResponse response = context.Variables.GetValueOrDefault<IResponse>("claudeTokenResponse", null);
                if (response == null || response.StatusCode != 200
                    || response.Headers.GetValueOrDefault("Content-Type", "").Split(';')[0].Trim() != "application/json") { return ""; }
                string body = response.Body.As<string>();
                if (body.Length > 20000) { return ""; }
                JObject token = JObject.Parse(body);
                if (token["error"] != null || token["access_token"]?.Type != JTokenType.String
                    || token["token_type"]?.Type != JTokenType.String || token.Value<string>("token_type") != "Bearer"
                    || token["expires_in"]?.Type != JTokenType.Integer
                    || (token["scope"] != null && (token["scope"].Type != JTokenType.String || token.Value<string>("scope") != "https:" + "/" + "/ai.azure.com/.default"))) { return ""; }
                long lifetime;
                string access = token.Value<string>("access_token");
                if (!long.TryParse(token["expires_in"].ToString(), out lifetime)
                    || lifetime < 120 || lifetime > 7200
                    || !System.Text.RegularExpressions.Regex.IsMatch(access, @"\A[A-Za-z0-9._~+/-]{32,16384}={0,2}\z")) { return ""; }
                return access;
            }
